    private ModBlocks() {
    }

    private static BlockBehaviour.Properties ore(MapColor color, boolean deep) {
        return BlockBehaviour.Properties.of().mapColor(color).strength(deep ? 4.5f : 3.0f, 3.0f).requiresCorrectToolForDrops().sound(deep ? SoundType.DEEPSLATE : SoundType.STONE);
    }

    private static RegistryObject<Block> oreBlock(String name, MapColor color, boolean deep, int minXp, int maxXp) {
        return BLOCKS.register(name, () -> new DropExperienceBlock(ModBlocks.ore(color, deep), (IntProvider)UniformInt.of((int)minXp, (int)maxXp)));
    }


    private static BlockBehaviour.Properties bombProps() {
        return BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(4.0f, 20.0f).sound(SoundType.METAL).noOcclusion().pushReaction(PushReaction.BLOCK).noLootTable();
    }
